using System;using System.Data.SqlClient;using System.Drawing;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;namespace AshkanJobCenter.UI{public class TalentPage:UserControl{DataGridView grid;TextBox search;public TalentPage(){BackColor=Theme.Background;var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=52};search=Ui.Text();search.Width=280;var b=Ui.Button(L.T("search"),false);b.Click+=(s,e)=>LoadData();top.Controls.Add(search);top.Controls.Add(b);Controls.Add(top);grid=Ui.Grid();Controls.Add(grid);grid.BringToFront();LoadData();}void LoadData(){var q="%"+search.Text.Trim()+"%";grid.DataSource=Database.Query("SELECT c.Id,c.FullName,c.City,c.PrimarySkill,c.ExperienceYears,COUNT(s.Id) SkillCount FROM Candidates c LEFT JOIN CandidateSkills s ON s.CandidateId=c.Id WHERE c.FullName LIKE @q OR c.PrimarySkill LIKE @q OR ISNULL(s.Skill,'') LIKE @q GROUP BY c.Id,c.FullName,c.City,c.PrimarySkill,c.ExperienceYears ORDER BY c.ExperienceYears DESC",new SqlParameter("@q",q));}}}